internal static class WindowsBrightnessGuiTests {
 static int checks,layouts;static readonly DateTime Now=new DateTime(2026,10,14,12,0,0,DateTimeKind.Utc);
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string text){checks++;if(!value)throw new Exception(text);}
 static Dictionary<string,object> Map(params object[] pairs){var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result[(string)pairs[i]]=pairs[i+1];return result;}
 static Dictionary<string,object> Monitor(int value=50,bool supported=true){return Map("id","brightness-"+new string('a',64),"name","Synthetic panel","fingerprint",new string('b',64),"currentBrightness",value,"levels",new[]{0,25,50,75,100},"supportsWrite",supported,"unavailableReason",supported?null:"METHOD_NOT_PAIRED");}
 static Dictionary<string,object> Data(int current=50,bool supported=true){return Map("schema",1,"sessionToken",new string('c',32),"readToken",new string('d',32),"capturedAtUtc",Now.ToString("o"),"expiresAfterMilliseconds",30000,"monitors",new[]{Monitor(current,supported)});}
 sealed class Fake:IWindowsBrightnessGuiBackend {
  internal object Session=new object();internal int Reads,SetRequests,SetFrames,Disposed;internal bool Defer,Quarantined;internal readonly TaskCompletionSource<bool> Release=new TaskCompletionSource<bool>();internal Dictionary<string,object> ReadData=Data();internal Action<Dictionary<string,object>> MutateResult;
  public object SessionIdentity {get{return Disposed==0?Session:null;}}
  public bool WritesAvailable {get{return Disposed==0&&!Quarantined;}}
  public async Task<WindowsBrightnessReply> Request(Dictionary<string,object> request,object expected,Action beforeSend){string op=(string)request["op"];if(op=="set"){SetRequests++;if(Defer)await Release.Task;if(expected==null||!Object.ReferenceEquals(expected,SessionIdentity))throw new WindowsBrightnessFailure("SESSION_EXPIRED");beforeSend();SetFrames++;int value=(int)request["brightness"];var original=((Dictionary<string,object>[])ReadData["monitors"])[0];bool same=(int)original["currentBrightness"]==value;var result=Map("schema",1,"alreadyCurrent",same,"writeAttempted",!same,"readbackConfirmed",true,"methodReturnCode",same?null:(object)0,"errorCode",null,"originalBrightness",original["currentBrightness"],"observed",Monitor(value));if(MutateResult!=null)MutateResult(result);return new WindowsBrightnessReply{ok=true,data=result};}if(op!="read")throw new Exception("Unexpected op");beforeSend();Reads++;return new WindowsBrightnessReply{ok=true,data=ReadData};}
  public void Dispose(){Disposed++;}
