 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string method,params object[] values){return typeof(MainWindow).GetMethod(method,Hidden).Invoke(window,values);}
 static IEnumerable<T> Logical<T>(DependencyObject root)where T:DependencyObject {if(root is T)yield return (T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var node=child as DependencyObject;if(node!=null)foreach(var item in Logical<T>(node))yield return item;}}
 static T Tag<T>(DependencyObject root,string tag)where T:FrameworkElement{return Logical<T>(root).Single(c=>Object.Equals(c.Tag,tag));}
 static void NoIo(MainWindow window){Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null&&new WindowInteropHelper(window).Handle==IntPtr.Zero,"no native HWND/show");foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(f=>f.FieldType==typeof(WorkerClient))){var worker=(WorkerClient)field.GetValue(window);Check(worker==null||typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"no external worker "+field.Name);}Check(((Dictionary<string,WorkerClient>)Field(window,"sdkWorkers")).Count==0,"no SDK client created");}
 static void Failed(Func<Task> callback,string message){bool failed=false;try{callback().GetAwaiter().GetResult();}catch(WindowsBrightnessFailure){failed=true;}catch(InvalidOperationException){failed=true;}Check(failed,message);}
 static void NativeBackendInert(){const string key="OpenAC.WindowsBrightness.WriteQuarantine.v1";object previous=AppDomain.CurrentDomain.GetData(key);try{AppDomain.CurrentDomain.SetData(key,null);var first=new WindowsBrightnessWorkerBackend();var worker=(WorkerClient)typeof(WindowsBrightnessWorkerBackend).GetField("worker",Hidden).GetValue(first);Check(first.SessionIdentity==null&&first.WritesAvailable&&typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"native backend construction neither starts worker nor queries WMI");AppDomain.CurrentDomain.SetData(key,true);var second=new WindowsBrightnessWorkerBackend();Check(!first.WritesAvailable&&!second.WritesAvailable,"session quarantine is shared across replacement backend instances");Failed(()=>second.Request(Map("op","set"),new object(),()=>{}),"quarantined native setter refuses before worker start");var other=(WorkerClient)typeof(WindowsBrightnessWorkerBackend).GetField("worker",Hidden).GetValue(second);Check(typeof(WorkerClient).GetField("process",Hidden).GetValue(other)==null,"quarantine rejection starts no external process");first.Dispose();second.Dispose();AppDomain.CurrentDomain.SetData(key,null);first=new WindowsBrightnessWorkerBackend();typeof(WindowsBrightnessWorkerBackend).GetField("pendingSets",Hidden).SetValue(first,1);first.Dispose();Check(Object.Equals(AppDomain.CurrentDomain.GetData(key),true),"disposing a pending setter retains uncertain-write quarantine");second=new WindowsBrightnessWorkerBackend();Check(!second.WritesAvailable,"next preview backend cannot clear pending-set quarantine");second.Dispose();}finally{AppDomain.CurrentDomain.SetData(key,previous);}}
 static async Task EarlyUnknownCompletion(){const string key="OpenAC.WindowsBrightness.WriteQuarantine.v1";object previous=AppDomain.CurrentDomain.GetData(key);try{foreach(string code in new[]{"METHOD_EXCEPTION","INVALID_METHOD_RESULT"}){AppDomain.CurrentDomain.SetData(key,null);var fake=new Fake();fake.MutateResult=d=>{d["readbackConfirmed"]=false;d["methodReturnCode"]=null;d["errorCode"]=code;};var backend=new WindowsBrightnessWorkerBackend(()=>fake.SessionIdentity,fake.Request,fake.Dispose);var client=new WindowsBrightnessClient(backend,()=>Now);var capture=await client.ReadAsync();var result=await client.ApplyAsync(capture,capture.Monitors[0],75,()=>{});Check(!result.ReadbackConfirmed&&result.ErrorCode==code&&fake.SetFrames==1,"early method exception/invalid-return response is unconfirmed without outer timeout");Check(!client.WritesAvailable&&Object.Equals(AppDomain.CurrentDomain.GetData(key),true),"production response handler makes unknown completion sticky");var refreshed=await client.ReadAsync();Check(fake.Reads==2&&client.IsCurrent(refreshed)&&!client.WritesAvailable,"new read never clears early unknown-completion quarantine");Failed(()=>client.ApplyAsync(refreshed,refreshed.Monitors[0],75,()=>{}),"unknown native method cannot be repeated after reread");Check(fake.SetFrames==1&&fake.SetRequests==1,"zero additional SET frames after early failure");var replacement=new WindowsBrightnessWorkerBackend(()=>fake.SessionIdentity,fake.Request,()=>{});Check(!replacement.WritesAvailable,"replacement backend retains unknown-completion quarantine");client.Dispose();replacement.Dispose();}
   AppDomain.CurrentDomain.SetData(key,null);var contradiction=new Fake();contradiction.MutateResult=d=>{d["errorCode"]="INVALID_METHOD_RESULT";};var contradictoryBackend=new WindowsBrightnessWorkerBackend(()=>contradiction.SessionIdentity,contradiction.Request,contradiction.Dispose);var reader=new WindowsBrightnessClient(contradictoryBackend,()=>Now);var old=await reader.ReadAsync();Failed(()=>reader.ApplyAsync(old,old.Monitors[0],75,()=>{}),"invalid method result cannot claim confirmed application");Check(!reader.WritesAvailable,"contradictory confirmed response also quarantines before parsing");reader.Dispose();
   AppDomain.CurrentDomain.SetData(key,null);var mismatch=new Fake();mismatch.MutateResult=d=>{d["readbackConfirmed"]=false;d["errorCode"]="READBACK_MISMATCH";d["observed"]=Monitor(50);};var completedBackend=new WindowsBrightnessWorkerBackend(()=>mismatch.SessionIdentity,mismatch.Request,mismatch.Dispose);reader=new WindowsBrightnessClient(completedBackend,()=>Now);old=await reader.ReadAsync();var unconfirmed=await reader.ApplyAsync(old,old.Monitors[0],75,()=>{});Check(!unconfirmed.ReadbackConfirmed&&reader.WritesAvailable,"completed ACK/readback mismatch alone is not classified as a continuing method");reader.Dispose();
  }finally{AppDomain.CurrentDomain.SetData(key,previous);}}
 static async Task Client(){
  var fake=new Fake();DateTime now=Now;var client=new WindowsBrightnessClient(fake,()=>now);Check(fake.Reads==0&&fake.SetFrames==0,"client constructor is inert");var capture=await client.ReadAsync();Check(client.IsCurrent(capture)&&capture.Monitors.Count==1&&capture.Monitors[0].CurrentBrightness==50,"parsed current capture is owner/session bound");var publicJson=new JavaScriptSerializer().Serialize(capture);Check(!publicJson.Contains("SessionToken")&&!publicJson.Contains("ReadToken")&&!publicJson.Contains("WorkerSession")&&!publicJson.Contains("InstanceName"),"public capture excludes executable credentials/raw monitor identity");int gates=0;var outcome=await client.ApplyAsync(capture,capture.Monitors[0],75,()=>gates++);Check(outcome.ReadbackConfirmed&&outcome.WriteAttempted&&!outcome.AlreadyCurrent&&gates>=3&&fake.SetFrames==1,"explicit apply calls terminal validation and distinguishes actual result");Check(!client.IsCurrent(capture),"every attempted transaction consumes old capture");Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"consumed capture never sends twice");Check(fake.SetFrames==1,"no retry from old capture");
  fake=new Fake{ReadData=Data(0)};client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();Check(capture.Monitors[0].CurrentBrightness==0,"real zero retained in GUI model");outcome=await client.ApplyAsync(capture,capture.Monitors[0],0,()=>{});Check(outcome.AlreadyCurrent&&!outcome.WriteAttempted&&outcome.ReadbackConfirmed&&!outcome.MethodReturnCode.HasValue,"same-value result has no method ACK/write evidence");
  fake=new Fake();client=new WindowsBrightnessClient(fake,()=>now);now=Now;capture=await client.ReadAsync();now=Now.AddSeconds(30.001);Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"expired capture fails before backend");Check(fake.SetRequests==0,"expired no-frame boundary");now=Now.AddMilliseconds(-1);Check(!client.IsCurrent(capture),"clock reversal cannot extend capture");now=Now;
  fake=new Fake();client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();fake.Session=new object();Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"worker restart cannot inherit capture");Check(fake.SetRequests==0,"session restart blocks before transport");
  fake=new Fake();client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();var foreign=new WindowsBrightnessClient(fake,()=>Now);Failed(()=>foreign.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"another controller cannot reuse capture owner");Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],51,()=>{}),"unenumerated percentage rejected");Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{throw new InvalidOperationException("disabled");}),"default-off policy sends nothing");Check(fake.SetRequests==0,"invalid owner/level/policy never enters backend set");var newer=await client.ReadAsync();Check(!client.IsCurrent(capture)&&client.IsCurrent(newer),"new read immediately retires the previous client capture");Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"retired capture never reaches backend after new read");Check(fake.SetRequests==0,"newer read cannot make old buttons executable");
  fake=new Fake{Defer=true};client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();bool permitted=true;var pending=client.ApplyAsync(capture,capture.Monitors[0],75,()=>{if(!permitted)throw new InvalidOperationException("revoked");});Check(!pending.IsCompleted&&fake.SetRequests==1&&fake.SetFrames==0,"queued apply is tracked before final frame");permitted=false;fake.Release.SetResult(true);Failed(()=>pending,"revocation during queue fails terminal guard");Check(fake.SetFrames==0,"late policy revocation sends no frame");
  fake=new Fake();client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();fake.Quarantined=true;Check(client.IsCurrent(capture)&&!client.WritesAvailable,"quarantine preserves read evidence but disables write capability");Failed(()=>client.ApplyAsync(capture,capture.Monitors[0],75,()=>{}),"unknown prior write blocks new setters before transport");Check(fake.SetRequests==0,"quarantined setter has zero frames");capture=await client.ReadAsync();Check(fake.Reads==2&&client.IsCurrent(capture)&&!client.WritesAvailable,"quarantined transport still permits explicit read only");
  foreach(Action<Dictionary<string,object>> mutation in new Action<Dictionary<string,object>>[]{d=>d["methodReturnCode"]="0",d=>d["readbackConfirmed"]=false,d=>d["observed"]=Monitor(50),d=>d["originalBrightness"]=25}){fake=new Fake();fake.MutateResult=mutation;client=new WindowsBrightnessClient(fake,()=>Now);capture=await client.ReadAsync();try{outcome=await client.ApplyAsync(capture,capture.Monitors[0],75,()=>{});Check(!outcome.ReadbackConfirmed,"unconfirmed result never claimed as applied");}catch(WindowsBrightnessFailure){Check(true,"contradictory/invalid result rejected");}}
  foreach(Action<Dictionary<string,object>> mutation in new Action<Dictionary<string,object>>[]{d=>d["schema"]=2,d=>d["sessionToken"]="bad",d=>d["capturedAtUtc"]=Now.AddSeconds(1).ToString("o"),d=>d["monitors"]=new[]{Monitor(),Monitor()},d=>((Dictionary<string,object>[])d["monitors"])[0]["currentBrightness"]=101,d=>((Dictionary<string,object>[])d["monitors"])[0]["levels"]=new[]{0,50,50},d=>((Dictionary<string,object>[])d["monitors"])[0]["supportsWrite"]="true"}){fake=new Fake();mutation(fake.ReadData);client=new WindowsBrightnessClient(fake,()=>Now);Failed(async()=>{await client.ReadAsync();},"invalid brightness data cannot enable controls");Check(fake.SetFrames==0,"bad data reads never imply a setting");}
 }
 static void Views(){var window=new MainWindow(true);Set(window,"windowsBrightnessNow",new Func<DateTime>(()=>Now));var fake=new Fake{ReadData=Data(0)};var client=new WindowsBrightnessClient(fake,()=>Now);var snapshot=client.ReadAsync().GetAwaiter().GetResult();Set(window,"windowsBrightnessClient",client);Set(window,"windowsBrightness",snapshot);foreach(double width in new[]{1180.0,1538.0}){((StackPanel)Field(window,"content")).Children.Clear();((Dictionary<string,int>)Field(window,"windowsBrightnessDraft")).Clear();Invoke(window,"AddWindowsBrightnessControls");var frame=(FrameworkElement)window.Content;frame.Measure(new Size(width,826));frame.Arrange(new Rect(0,0,width,826));frame.UpdateLayout();layouts++;string id=snapshot.Monitors[0].Id;var combo=Tag<ComboBox>(frame,"brightness-level:"+id);Check(combo.SelectedIndex==0&&Convert.ToString(combo.SelectedItem)=="0 %","display and draft both preserve zero");Check(!Tag<Button>(frame,"brightness-apply:"+id).IsEnabled&&!Tag<Button>(frame,"brightness-read").IsEnabled,"render/default-off prevents reads and settings");combo.SelectedIndex=3;Check(((Dictionary<string,int>)Field(window,"windowsBrightnessDraft"))[id]==75&&fake.SetFrames==0&&fake.Reads==1,"selection updates local draft only");NoIo(window);}
  Set(window,"render",false);((Task)Invoke(window,"ApplyWindowsBrightness",snapshot,snapshot.Monitors[0],75)).GetAwaiter().GetResult();Check(fake.SetRequests==0&&!(bool)Field(window,"busy"),"default-off UI callback makes no backend request");Set(window,"render",true);var expired=new WindowsBrightnessClient(new Fake(),()=>Now.AddSeconds(31));Set(window,"windowsBrightnessClient",expired);((StackPanel)Field(window,"content")).Children.Clear();Invoke(window,"AddWindowsBrightnessControls");Check(!Logical<Button>((DependencyObject)window.Content).Any(b=>Convert.ToString(b.Tag).StartsWith("brightness-apply:")),"old-owner/expired capture hides actionable controls");NoIo(window);
 }
 static void Closing(){var window=new MainWindow(true);Set(window,"windowsBrightnessNow",new Func<DateTime>(()=>Now));Set(window,"render",false);Set(window,"page","屏幕设置");var fake=new Fake{Defer=true};var client=new WindowsBrightnessClient(fake,()=>Now);var snapshot=client.ReadAsync().GetAwaiter().GetResult();Set(window,"windowsBrightnessClient",client);Set(window,"windowsBrightness",snapshot);((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);var applying=(Task)Invoke(window,"ApplyWindowsBrightness",snapshot,snapshot.Monitors[0],75);Check(!applying.IsCompleted&&!window.WindowsBrightnessCanPreviewReload&&(bool)Field(window,"busy"),"active brightness operation blocks preview replacement");Set(window,"closing",true);var stopping=(Task)Invoke(window,"DisposeWindowsBrightnessAsync");Check(fake.Disposed==1&&!stopping.IsCompleted,"closing disposes isolated transport and joins request lifetime");fake.Release.SetResult(true);applying.GetAwaiter().GetResult();stopping.GetAwaiter().GetResult();Check(fake.SetFrames==0&&window.WindowsBrightnessCanPreviewReload&&Field(window,"windowsBrightness")==null&&Field(window,"windowsBrightnessTask")==null,"closing prevents queued SET, waits, clears stale state");NoIo(window);}
 static void Expiry(){var window=new MainWindow(true);var fake=new Fake{ReadData=Data(0)};var client=new WindowsBrightnessClient(fake,()=>Now);var snapshot=client.ReadAsync().GetAwaiter().GetResult();Set(window,"windowsBrightnessClient",client);Set(window,"windowsBrightness",snapshot);Set(window,"windowsBrightnessNow",new Func<DateTime>(()=>Now.AddMilliseconds(30001)));var draft=(Dictionary<string,int>)Field(window,"windowsBrightnessDraft");draft[snapshot.Monitors[0].Id]=75;Check(Field(window,"windowsBrightnessExpiryTimer")==null,"render-only setup does not start expiry timer");Check(!(bool)Invoke(window,"ExpireWindowsBrightness",Now.AddMilliseconds(29999))&&!(bool)Invoke(window,"ExpireWindowsBrightness",Now.AddMilliseconds(30000)),"capture remains valid through exact lease boundary");Check((bool)Invoke(window,"ExpireWindowsBrightness",Now.AddMilliseconds(30001))&&Field(window,"windowsBrightness")==null&&draft.Count==0&&!client.IsCurrent(snapshot),"expiry retires old token/draft and clears current numbers");((StackPanel)Field(window,"content")).Children.Clear();Invoke(window,"AddWindowsBrightnessControls");Check(!Logical<Button>((DependencyObject)window.Content).Any(b=>Convert.ToString(b.Tag).StartsWith("brightness-apply:"))&&!Logical<TextBlock>((DependencyObject)window.Content).Any(t=>t.Text=="0 %"),"expired page has neither old numeric nor actionable apply control");Set(window,"render",false);((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);((Task)Invoke(window,"ApplyWindowsBrightness",snapshot,snapshot.Monitors[0],75)).GetAwaiter().GetResult();Check(fake.Reads==1&&fake.SetRequests==0,"expiry helper/rebuild/old button cannot initiate GET or SET");Set(window,"windowsBrightnessExpiryTimer",new System.Windows.Threading.DispatcherTimer());((Task)Invoke(window,"DisposeWindowsBrightnessAsync")).GetAwaiter().GetResult();Check(Field(window,"windowsBrightnessExpiryTimer")==null,"dispose detaches and stops pure expiry lifecycle");NoIo(window);